                easeSine = easeSine, easeExpo = easeExpo, easeElastic = easeElastic,
                HashOut = hashOut,
            };
            job.Run();

            var result = new[]
            {
                ("dft-signal/dft.double.n32", hashOut[0]),
                ("dft-signal/idft.double.n32", hashOut[1]),
                ("dft-signal/phase.double.n16", hashOut[2]),
                ("dft-signal/window.double.n32.all4", hashOut[3]),
                ("dft-signal/gaussianKernel.double.n15", hashOut[4]),
                ("dft-signal/gaussianKernel2D.double.7x7", hashOut[5]),
                ("dft-signal/gallery.prolate.double.n16", hashOut[6]),
                ("dft-signal/wave.sine.double.n32", hashOut[7]),
                ("dft-signal/easing.sine-expo-elastic.double.n32", hashOut[8]),
            };
            hashOut.Dispose();
            dftInRe.Dispose(); dftInIm.Dispose(); dftOutRe.Dispose(); dftOutIm.Dispose();
            idftOutRe.Dispose(); idftOutIm.Dispose();
            phaseRe.Dispose(); phaseIm.Dispose(); phaseDest.Dispose();
            windowDest.Dispose(); gaussKernel.Dispose(); gaussKernel2D.Dispose(); prolate.Dispose();
            waveDest.Dispose(); easingDest1.Dispose(); easingDest2.Dispose(); easingDest3.Dispose();
            return result;
        }
    }
}
